      {'type': 'table', 'title': '1원당 효용 비교', 'columns': ['재화', '한계효용', '가격', '1원당 효용'], 'rows': [['X재', '2', '3원', '약 0.67'], ['Y재', '0.5', '1원', '0.5']], 'caption': 'X재의 1원당 효용이 더 크니 X재를 늘리고 Y재를 줄여요.'},
